// bulk.mjs — parallel probe driver.
// Usage: node bulk.mjs <jsonl-file-of-domains> <out.jsonl> [strict] [concurrency]
import { execFile } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
const EXE = '/workspace/dataset/test3_executable';
const [,, inFile, outFile, strict = 'True', conc = '24'] = process.argv;
const domains = readFileSync(inFile, 'utf8').split('\n').filter(l => l.length).map(l => JSON.parse(l));
const results = new Array(domains.length);
let next = 0;
function one(i) {
  return new Promise(res => {
    execFile(EXE, ['--domain', domains[i], '--strict', strict], { encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 },
      (err, stdout, stderr) => { results[i] = { i, rc: err ? (err.code ?? err.status ?? 1) : 0, out: stdout, err: stderr }; res(); });
  });
}
async function worker() { while (next < domains.length) { await one(next++); } }
await Promise.all(Array.from({ length: Math.min(+conc, domains.length) }, worker));
writeFileSync(outFile, results.map(r => JSON.stringify(r)).join('\n') + '\n');
console.error(`done ${domains.length}`);
import { run } from './probe.mjs';
const cps = process.argv.slice(2).map(s => parseInt(s, 16));
for (const cp of cps) {
  const ch = String.fromCodePoint(cp);
  const r = run(ch + '.cn');
  const lines = r.out.split('\n');
  console.log(`U+${cp.toString(16).toUpperCase().padStart(4,'0')} rc=${r.rc} | L1=${JSON.stringify(lines[0])} | L2=${JSON.stringify(lines[1])}`);
}
// probe.mjs — run the executable with a domain built from codepoints
import { execFileSync } from 'node:child_process';
const EXE = '/workspace/dataset/test3_executable';
export function run(domain, strict = 'True') {
  try {
    const out = execFileSync(EXE, ['--domain', domain, '--strict', strict],
      { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
    return { rc: 0, out, err: '' };
  } catch (e) {
    return { rc: e.status, out: e.stdout ?? '', err: e.stderr ?? '' };
  }
}
